text:
We summarize the finalized CRIME-Q appraisal for the included studies. We use the adapted items defined in the appraisal workbook to assess quality of reporting, methodological quality, and risk of bias (Andersen et al. 2024). The code below reads the item definitions and ratings from the same workbook so their order remains aligned.
We load the finalized study ratings and adapted item definitions from the CRIME-Q workbook.
Show data-loading code
# Read the finalized study-level ratings.
appraisal &lt;- readxl::read_excel(
  path = input_file,
  sheet = "CRIME-Q_Appraisal",
  col_types = "text",
  na = ""
) |&gt;
  dplyr::mutate(
    dplyr::across(
      dplyr::everything(),
      ~ dplyr::na_if(stringr::str_squish(.x), "")
    )
  )

# Read the codebook table below the rating legend.
codebook_raw &lt;- readxl::read_excel(
  path = input_file,
  sheet = "Codebook",
  skip = 7,
  col_types = "text",
  na = ""
)

# Assign concise names to the five codebook columns.
names(codebook_raw)[1:5] &lt;- c(
  "item",
  "item_name",
  "domain",
  "question",
  "criteria"
)

# Match the rating options recorded at the end of each question.
rating_pattern &lt;- "(Yes|Partly|No|Unclear|NA)(/(Yes|Partly|No|Unclear|NA))+$"

# Keep the 21 scored items and omit their paired notes fields.
codebook &lt;- codebook_raw |&gt;
  dplyr::mutate(
    dplyr::across(
      dplyr::everything(),
      ~ dplyr::na_if(stringr::str_squish(.x), "")
    )
  ) |&gt;
  dplyr::filter(
    domain %in% c("QoR", "MQ", "RoB"),
    !stringr::str_detect(item, "n$|_n$")
  ) |&gt;
  dplyr::mutate(
    item_key = stringr::str_remove_all(item, "[^[:alnum:]]"),
    ratings = stringr::str_replace_all(
      stringr::str_extract(question, rating_pattern),
      "/",
      "; "
    ),
    definition = stringr::str_squish(
      stringr::str_remove(
        question,
        paste0("\\s*", rating_pattern)
      )
    )
  )
Show validation code
# Select rating columns while excluding notes and appraisal time.
score_columns &lt;- names(appraisal)[
  stringr::str_detect(names(appraisal), "^[0-9]+[A-Z]") &
    !stringr::str_detect(names(appraisal), "notes$")
]

# Match workbook column prefixes to the item codes in the codebook.
score_keys &lt;- stringr::str_extract(score_columns, "^[^_]+")

if (!identical(score_keys, codebook$item_key)) {
  stop("The CRIME-Q rating columns do not match the codebook item order.")
}

if (anyDuplicated(appraisal$study_id) &gt; 0L || anyNA(appraisal$study_id)) {
  stop("Each CRIME-Q row must have one unique study_id.")
}

# Convert the rating matrix to long format for validation and plotting.
item_map &lt;- tibble::tibble(
  score_column = score_columns,
  item = codebook$item,
  domain = codebook$domain
)

plot_data &lt;- appraisal |&gt;
  dplyr::select(study_id, dplyr::all_of(score_columns)) |&gt;
  tidyr::pivot_longer(
    cols = dplyr::all_of(score_columns),
    names_to = "score_column",
    values_to = "rating"
  ) |&gt;
  dplyr::left_join(item_map, by = "score_column")

valid_ratings &lt;- c("Yes", "Partly", "No", "Unclear", "NA")

if (anyNA(plot_data$rating)) {
  stop("The CRIME-Q appraisal contains a missing rating.")
}

unexpected_ratings &lt;- setdiff(unique(plot_data$rating), valid_ratings)

if (length(unexpected_ratings) &gt; 0L) {
  stop(
    "Unexpected CRIME-Q rating: ",
    paste(unexpected_ratings, collapse = ", ")
  )
}

if (anyNA(codebook$ratings)) {
  stop("A CRIME-Q item does not contain a recorded rating list.")
}

What this site contains
This online supplement provides the computational workflow for the systematic review and multilevel meta-analysis of prenatal chronic noise exposure and offspring behavioural outcomes in laboratory rodents.
It includes:

preparation of the analysis database from the original extraction file;
calculation of lnRR, lnVR, lnCVR, and their sampling variances;
construction of the sampling variance-covariance matrix for each effect-size type;
estimation of the overall lnRR, lnVR, and lnCVR with multilevel intercept-only models;
separate multilevel meta-regressions for each effect-size type and moderator;
publication-bias diagnostics for small-study effects and time-lag patterns;
the adapted CRIME-Q appraisal for each included study;
study-level leave-one-out and combined Abramova-laboratory exclusion analyses;
an appendix sensitivity analysis that excludes exact-zero-corrected effect sizes.



How to navigate

Data preparation calculates missing statistics and creates the two derived databases.
Effect size calculation calculates lnRR, lnVR, lnCVR, and their sampling variances and reports their distributions.
Sampling variance-covariance matrices constructs and checks one V matrix for each effect-size type with metafor.
Overall effects fits one intercept-only multilevel meta-analytic model for lnRR, lnVR, and lnCVR.
Uni-moderators subsets the matching V and fits one multilevel meta-regression for each effect-size type and moderator.
Publication bias displays the funnel plot and fits the small-study and publication-year models.
CRIME-Q appraisal displays the adapted item definitions and finalized study-level ratings.
Leave-one-out analysis removes each study in turn and refits the overall lnRR model.
Sensitivity analysis excludes the Abramova-laboratory studies and the exact-zero-corrected effect sizes in an appendix.



Reproducibility
We run all data preparation and analyses in R through Quarto. We read the original extraction file without overwriting it. Each chapter creates the data or model object required by the following chapter.

Direction harmonisation
When higher_better == "yes", we multiply lnRR by -1 to keep the behavioural direction consistent across effect sizes. After this harmonisation, a positive lnRR represents more anxiety- or depression-like behaviour in the treatment group, while a negative lnRR represents less anxiety- or depression-like behaviour.
We do not reverse lnVR or lnCVR because standard deviations do not have an anxiety- or depression-like direction. For both variability metrics, positive values represent greater variability in the treatment group and negative values represent lower variability.
The following functions apply these rules while preserving the original row order.

# Return the smallest positive value in a vector.
minimum_positive &lt;- function(x) {
  x &lt;- x[is.finite(x) & x &gt; 0]
  if (length(x) == 0) NA_real_ else min(x)
}

apply_zero_sd_corrections &lt;- function(data) {
  strata &lt;- c("assay_type", "measurement_variable", "data_type", "data_units")

  # Calculate the smallest positive SD within each outcome stratum and arm.
  local_minima &lt;- data |&gt;
    group_by(across(all_of(strata))) |&gt;
    summarise(
      minimum_control_sd = minimum_positive(c_sd),
      minimum_exposed_sd = minimum_positive(ex_sd),
      .groups = "drop"
    )

  corrected &lt;- data |&gt;
    left_join(local_minima, by = strata) |&gt;
    mutate(
      c_sd_continuity_corrected = !is.na(c_sd) & c_sd == 0,
      ex_sd_continuity_corrected = !is.na(ex_sd) & ex_sd == 0,
      c_sd = if_else(c_sd_continuity_corrected, minimum_control_sd, c_sd),
      ex_sd = if_else(ex_sd_continuity_corrected, minimum_exposed_sd, ex_sd)
    )

  if (any(corrected$c_sd_continuity_corrected & is.na(corrected$minimum_control_sd)) ||
      any(corrected$ex_sd_continuity_corrected & is.na(corrected$minimum_exposed_sd))) {
    stop("A zero SD has no positive SD in the same treatment arm and outcome stratum.")
  }

  corrected |&gt;
    select(-minimum_control_sd, -minimum_exposed_sd)
}

apply_nonpercentage_corrections &lt;- function(data) {
  strata &lt;- c("assay_type", "measurement_variable", "data_type", "data_units")

  # Calculate the smallest positive mean within each outcome stratum and arm.
  local_minima &lt;- data |&gt;
    group_by(across(all_of(strata))) |&gt;
    summarise(
      minimum_control_mean = minimum_positive(c_mean),
      minimum_exposed_mean = minimum_positive(ex_mean),
      .groups = "drop"
    )

  global_control_minimum &lt;- minimum_positive(data$c_mean)
  global_exposed_minimum &lt;- minimum_positive(data$ex_mean)

  data |&gt;
    left_join(local_minima, by = strata) |&gt;
    mutate(
      c_mean_continuity_corrected = !is.na(c_mean) & c_mean == 0,
      ex_mean_continuity_corrected = !is.na(ex_mean) & ex_mean == 0,
      c_mean = if_else(
        c_mean_continuity_corrected,
        0.9 * coalesce(minimum_control_mean, global_control_minimum),
        c_mean
      ),
      ex_mean = if_else(
        ex_mean_continuity_corrected,
        0.9 * coalesce(minimum_exposed_mean, global_exposed_minimum),
        ex_mean
      )
    ) |&gt;
    select(-minimum_control_mean, -minimum_exposed_mean) |&gt;
    apply_zero_sd_corrections()
}

prepare_lnrr_data &lt;- function(data) {
  # Apply the non-percentage rules.
  nonpercentage &lt;- data |&gt;
    filter(data_type != "percentage") |&gt;
    apply_nonpercentage_corrections()

  # Apply the percentage rules.
  percentage &lt;- data |&gt;
    filter(data_type == "percentage") |&gt;
    mutate(
      c_mean_continuity_corrected = c_mean %in% c(0, 100),
      ex_mean_continuity_corrected = ex_mean %in% c(0, 100),
      c_mean = case_when(c_mean == 0 ~ 0.5, c_mean == 100 ~ 99.5, TRUE ~ c_mean),
      ex_mean = case_when(ex_mean == 0 ~ 0.5, ex_mean == 100 ~ 99.5, TRUE ~ ex_mean)
    ) |&gt;
    apply_zero_sd_corrections()

  # Recombine the rows in their original order.
  bind_rows(nonpercentage, percentage) |&gt;
    arrange(match(es_id, data$es_id))
}

We apply the boundary corrections and report the number of changes. The second table lists only the statistics that the rules modified.

db_prepared &lt;- prepare_lnrr_data(db)

boundary_corrections &lt;- db |&gt;
  select(
    es_id, study_id,
    c_mean_old = c_mean,
    ex_mean_old = ex_mean,
    c_sd_old = c_sd,
    ex_sd_old = ex_sd
  ) |&gt;
  left_join(
    db_prepared |&gt;
      select(
        es_id,
        c_mean_new = c_mean,
        ex_mean_new = ex_mean,
        c_sd_new = c_sd,
        ex_sd_new = ex_sd,
        c_mean_continuity_corrected,
        ex_mean_continuity_corrected,
        c_sd_continuity_corrected,
        ex_sd_continuity_corrected
      ),
    by = "es_id"
  ) |&gt;
  mutate(
    any_correction = c_mean_continuity_corrected |
      ex_mean_continuity_corrected |
      c_sd_continuity_corrected |
      ex_sd_continuity_corrected
  )

boundary_corrections |&gt;
  summarise(
    `Total effect sizes` = n(),
    `Any correction` = sum(any_correction),
    `Control mean` = sum(c_mean_continuity_corrected),
    `Exposed mean` = sum(ex_mean_continuity_corrected),
    `Control SD` = sum(c_sd_continuity_corrected),
    `Exposed SD` = sum(ex_sd_continuity_corrected)
  ) |&gt;
  knitr::kable(caption = "Boundary corrections by statistic.")


